import heapq
class PriorityQueue: 
    def __init__(self): self._queue = []
    def push(self, item, priority): self._queue.append((item, priority))
    def pop(self): item, priority = heapq.heappop(self._queue)
    def peek(self): return heapq.heappop(self._queue)[0]
def findTopK(lst, k): 
    heap = PriorityQueue() 
    for i in lst: heap.push(i, i) # assign the priority as value
    top_k_elements = [] # to store top k elements
    while len(top_k_elements) < k:
        top_k_elements.append(heap.peek())
    return top_k_elements

