"public static Heap insert(HeapNode node) {
    // Check if the node is null
    if (node == null)
        return null;

    // Create a temporary node
    HeapNode temp = new HeapNode(node.data);
    // Make the parent's child point to the temporary node
    temp.parent = node.parent;
    // If the parent is root, make it the temporary node's parent
    if (node.parent == null || node.parent.data > temp.data)
        node.parent = temp;
    else
        // Find the correct position for the temporary node
        while (node.parent.data > temp.data)
