"import heapq from 'heapq'; function dijkstra(graph, startNode) {
    let shortestDistances = {}; // initialize an object to store distances
    let unvisitedNodes = Object.keys(graph);
    while (unvisitedNodes.length > 0) {
        let currentNode = unvisitedNodes[0];
        let currentDistance = Infinity;
        for (let neighbor in graph[currentNode]) { // O(n) time complexity
            let distance = graph[currentNode][neighbor];
            if (distance < currentDistance) {
                currentDistance = distance;
                shortestDistances[currentNode] = neighbor;
            }
        }
        unvisitedNodes.splice(unvisitedNodes.indexOf(currentNode), 1);
    }
    return shortestDistances;
}

