std::mutex mtx;
std::condition_variable cv;

// Define a function to acquire the lock and check if it's held by another thread.
void acquireLock() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [&] { return !mtx.locked(); });
}

// Define a function to release the lock.
void releaseLock() {
    std::lock_guard<std::mutex> guard(mtx);
}

// Test thread 1. 
void testThread1() {
    acquireLock();
    // Simulate some work being done by Thread 2.
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    releaseLock();
}

// Test thread 2. 
void testThread2() {
    acquireLock();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    releaseLock();
}

