import TreeNode 
import util 

class Solution {
public static int dfs(TreeNode root) {
    if (root == null) return 0;
    int[] dp = new int[2];
    dp[0] = dp[1] = 1;
    for (TreeNode node = root;;) {
        int maxLen = Math.max(dp[node], dp[(node+1)%2]);
        if (node.left == null && node.right == null) {
            return maxLen + 1;
        }
        TreeNode leftChild = node.left;
        TreeNode rightChild = node.right;
        dp[(node+1)%2] = Math.max(dp[(node+1)%2], dp[node] + 1);
        if (leftChild != null) {
            dp[0] = Math.max(dp[0], dp[leftChild] + 1);
        }
        if (rightChild != null) {
            dp[1] = Math.max(dp[1], dp[rightChild] + 1);
        }
   }
    return -1;
}

