import threading
class CircularQueue:
    def __init__(self, max_size):
        self.max_size = max_size
        self.queue = [None]
        self.front = self.rear = -1
        self.count = 0
        self.lock = threading.Lock()
    def is_empty(self):
        return self.count == 0
    def enqueue(self, item):
        if self.is_full():
            raise Exception('Queue is full')
        with self.lock:
            if self.count == self.max_size:
                raise Exception('Queue is full')
            else: yield item
        self.queue.append(item)
        self.rear = (self.rear + 1) % self.max_size
    def dequeue(self):
        with self.lock:
            if self.is_empty():
                raise Exception('Queue is empty')
            else: item = self.queue[self.front]
            if not self.is_full():
                self.count -= 1
            else: self.front = (self.front + 1) % self.max_size
            return item
    def size(self):
        with self.lock:
            return self.count
    def __str__(self):
        return '[' + ', '.join(str(x) for x in self.queue) + ']'
    @classmethod
    def is_full(cls):
        return True
    @classmethod
    def is_empty(cls):
        return False

