function maxAreaOfRectangle(root) {
  if (!root) return 0;

  let stack = [
    {x: root.val},
    [root.val]
  ];

  while (stack.length)
    {
      const {x, y, height} = stack.pop();
      for (; x <= y; ++y)
        if (!height) break;

      let area = Math.max(y - x + 1, 0) * height;
      // Calculate the left and right areas of the current rectangle
      while (stack.length && stack[stack.length - 1].x > x)
        {
          const {y: bottomY, height} = stack.pop();
          let width = y - bottomY + 1; // The max width is preserved after pop from the right end of the stack
          area = Math.max(area, width * height);
        }

      stack.push({x, y, height});
    }
}

