    let maxSoFar = -Infinity,
        currentSum = 0;

    while (windowEnd < nums.length) {
        // Add the elements in the current window to the sum.
        currentSum += nums[windowEnd];

        // If we've reached the end of the array or added enough elements, check if we can find a non-overlapping part that's also long enough.
        while (currentSum > 0 && windowStart <= windowEnd && windowEnd < nums.length) {
            maxSoFar = Math.max(maxSoFar, currentSum);

            // Slide the window forward by moving the pointer of `windowStart` to the right and subtracting the left element.
            currentSum -= nums[windowStart];
            windowStart++;
        }

        windowEnd++;
    }

    return maxSoFar;
}

