        function sortAndFlatten(list) {
            if (list.length === 0) return [];

            const result = [];
            for (let i = 0; i < list.length; i++) { // O(n) time complexity due to nested loops
                if (typeof list[i] == 'number') { // check if element is an integer
                    let sortedI = sortAndFlatten(list.slice(i)); // recursive call on sorted sublist
                    result.push(sortedI[0]); // push the first element of the sorted sublist
                    for (let j = 1; j < sortedI.length; j++) {
                        result.push(sortedI[j] - sortedI[j-1]); // calculate and add differences to maintain sorted order
                    }
                } else { // not an integer, skip it
                    i--; // increment index if the element is not an integer
                }
            }
            return result;\
