def dynamic_programming(graph: list[list[int]]) -> int {
  dp = [[0 for _ in range(len(graph))] for __ in range(len(graph))]
  for i in range(len(graph)):
    for j in range(i):
      if graph[i][j] == 1:
        dp[i][j] = dp[j][i-1] + dp[j][j]+1

  return max(dp[-1])
}

