        if (isFull) {
            throw new Error('Queue is full');
        }
        Node newNode = new Node(data);
        if (!isEmpty) {
            rear.next = newNode;
            newNode.next = front;
            if (size == rear - front + 1)
                front = rear;
            else
                rear = rear.next;
        }
        size++;
        if (size == 0)
            isFull = false;
    }

    dequeue() {
        if (!isEmpty) {
            data = front.data;
            Node temp = front;
            front = front.next;
            if (front == null) {
                isFull = true;
                rear = null;
            } else {
                rear.next = temp;
                temp.next = null;
            }
            size--;
            if (size <= 1)
                isEmpty = true;
