from collections import deque
def height_of_binary_tree(root):
    if root is None:
        return 0
    queue = deque([root])
    while queue: 
        size = len(queue)
        for _ in range(size):
            current_node = queue.popleft() 
            if current_node.left:
                queue.append(current_node.left) 
            if current_node.right:
                queue.append(current_node.right) 
        queue.popleft()
    return size
