class SyntaxTreeNode { constructor(value) { this.value = value; } 

constructor(left, right) { this.left = left; this.right = right; };

function parse(expression) { let root = new SyntaxTreeNode(expression);
return parseHelper(root, expression); 

function parseHelper(node, expression) { if (expression.startsWith('(')) { // Left bracket
   let parts = expression.substring(1, expression.length - 2).split(' ');
   let type = parts[0];
   let value = [...parts].slice(1).join(' ');

if (type == 'cdot') { 
   node.left = new SyntaxTreeNode(parseHelper(node.left, parts.slice(1).join('.')));

} else if (type == '^') { // Exponentiation
   let baseNode = parseHelper(new SyntaxTreeNode(expression.substring(1)), [...parts].slice(2).join(' '));

node.right = new SyntaxTreeNode(baseNode.value);
}
else { throw new Error('Invalid syntax'); } 
return node; 
},

