    class SingletonMeta(type):
        _instances = {}\
        def __call__(self, *args, **kwargs):
            if self not in self._instances:
                self._instances[self] = super(SingletonMeta, self).__call__(*args, **kwargs)
            return self._instances[self]
    class Singleton(type):
        __new__ = SingletonMeta.__call\
    def __init__(self, *args, **kwargs):
        if not hasattr(self, '_instance'):
            self._instance = super(Singleton, self).__init__(*args, **kwargs)
            self._instance._destroy = None
        return self
    @classmethod\
    def _destroy(cls, instance):
        del cls._instances[cls.__name__]
        instance._destroy = None
    @classmethod\
    def _create(cls, instance, *args, **kwargs):
        return cls(*args, **kwargs)
    def __repr__(self):
        return 'Singleton instance'
    def _delete(self):
        del self._destroy
}

