function hasCycle(graph) {
  let visited = new Set();
  let stack = [];

  for (let node in graph)
  {
    if (!visited.has(node))
      if (hasCycleUtil(graph, node, visited, stack))
        return true;
    stack.push(node);
  }

  return false;

function hasCycleUtil(graph, node, visited, stack) {
  if (stack.indexOf(node) != -1)
   return true;

  for (let neighbor of graph[node])
   if (!visited.has(neighbor))
     if (hasCycleUtil(graph, neighbor, visited, stack))
       return true;

    return false;
}

