"import heapq
class PriorityQueue:
    def __init__(self):
        self._queue = []
        self._max_heap = []
    def push(self, item, priority):
        heapq.heappush(self._queue, (-priority, item))
        if len(self._queue) > len(self._max_heap):# to maintain max heap order
            heapq.heappop(self._max_heap)
        self._queue.append(item)
    def pop(self):
        if not self._queue: return None
        priority, item = heapq.heappop(self._queue)
        # If the removed element was the highest in the heap:
        if -priority < len(self._max_heap):# to maintain max heap order
            heapq.heappush(self._max_heap, (-priority, item))
        return item
    def size(self):
        return len(self._queue)
    def is_empty(self):
        return len(self._queue) == 0
}

