    function findNode(index) { 
        // Initialize two pointers, slow and fast. 
        let slow = head, fast = head 
        while (fast && fast.next) { 
            if (index == fast.next.val) return fast.next; 
            slow = slow.next; slow = slow.next 
        } 
        // If the list is empty or there's no node at index 4 
        if (!slow || slow.next.next) return null; 
        let nextNode = slow.next; 
        slow.next = null; 
        while (nextNode) { 
            let nextNext = nextNode.next; 
            nextNode.next = nextNext; 
            if (index == nextNext.val) return nextNode; 
            nextNode = nextNext 
        } 
        return null; 
    }
}

