function shortestPath(graph, start, end) {

    let queue = new PriorityQueue();

    queue.enqueue([start, 0]);

    while (!queue.isEmpty()) {
        let [node, weight] = queue.dequeue();

        if (node == end) {
            return weight;
        }

        for (let neighbor of graph[node]) {
            let tempWeight = weight + neighbor.weight;

            if (!queue.has(neighbor)) {
                queue.enqueue([neighbor, tempWeight]);
            }

       }
    }

    return -1;
}

