We'll use the following design principles to build our API:

- Authentication will be handled using JSON Web Tokens (JWT).
- Users will be authenticated based on their existing credentials.
- The API will use a secure secret key for signing and verifying tokens.
- We'll use the Passport.js library for authentication and authorization.
- The API will return an access token in each response to verify the user's identity.

Here's a simplified example of how we might implement this API using Express.js, Passport.js, and JWT:

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();
app.use(express.json());
// Define the User model
class User {    constructor(id, name, email) {        this.id = id;        this.name = name;        this.email = email;    }}
const users = [new User(1, 'John Doe', 'john@example.com')];
// Middleware to authenticate requests
app.use((req, res, next) => {
    const token = req.header('Authorization');
    if (!token) return res.status(401).send({ message: 'Unauthorized' });
    try {        const decoded = jwt.verify(token, process.env.SECRET_KEY);
        req.user = new User(decoded.id, decoded.name, decoded.email);
        next();
    } catch (error) {
        return res.status(401).send({ message: 'Invalid token' });
    }
});
// Define the API endpoint for user authentication
app.post('/login', (req, res) => {
    const email = req.body.email;
    const password = req.body.password;
    const user = users.find(user => user.email === email);
    if (!user || user.password !== password) return res.status(401).send({ message: 'Invalid credentials' });
    const token = jwt.sign({ id: user.id, name: user.name, email: user.email }, process.env.SECRET_KEY);
    res.send({ token });
});
// Define the API endpoint for authorizing access
app.get('/protected', (req, res) => {
    if (!req.user) return res.status(401).send({ message: 'Unauthorized' });
    const token = req.header('Authorization');
    try {        jwt.verify(token, process.env.SECRET_KEY);
        res.send({ message: 'Access granted' });
    } catch (error) {
        return res.status(401).send({ message: 'Invalid token' });
    }
});
// Define the API endpoint for getting user information
app.get('/user', (req, res) => {
    if (!req.user) return res.status(401).send({ message: 'Unauthorized' });
    const token = req.header('Authorization');
    try {        jwt.verify(token, process.env.SECRET_KEY);
        res.send({ name: req.user.name, email: req.user.email });
    } catch (error) {
        return res.status(401).send({ message: 'Invalid token' });
    }
});

