    if (!node) return 0;

    let leftHeight = getLeftHeight(node);
    let rightHeight = getRightHeight(node);

    if (leftHeight == rightHeight && leftHeight == -1) return -1;
    if (leftHeight != rightHeight || leftHeight < 0) return -1;

    let height = Math.max(leftHeight, rightHeight) + 1;

    function getLeftHeight(node) {
        if (!node.left) return -1;

        return getLeftHeight(node.left);
    }

    function getRightHeight(node) {
        if (!node.right) return -1;

        return getRightHeight(node.right);
    }

    return Math.max(height, getLongestPath(node.left), getLongestPath(node.right)) - 1;
}

