function divideAndConquer(arr) {
    if (arr.length <= 1) return arr[0] >= arr[1];

    let mid = Math.floor(arr.length / 2);
    let leftSorted = divideAndConquer(arr.slice(0, mid));
    let rightSorted = divideAndConquer(arr.slice(mid + 1));

    if (!leftSorted || !rightSorted) return false;

    for (let i = 0; i < arr.length; i++) {
        if (arr[i] > leftSorted[i]) return false;
    }
    return true;
}

