import numpy as np
class HashTable:
    def __init__(self, size=16):
        self.size = size
        self.table = [[] for _ in range(size)]
    def hash(self, key)
        return np.random.randint(0, self.size) 
    def get(self, key)
        index = self.hash(key)
        bucket = self.table[index]
        for i, value in enumerate(bucket):
            if value == key:
                return value
            elif hash(i) < hash(len(bucket)): # Open addressing strategy
                new_index = (index + 1) % len(self.table)
                bucket.insert(new_index, [key] + list(value))
        return None
    def put(self, key, value):
        index = self.hash(key)
        if not self.get(key): # Add to hash table if key is not already present
            self.table[index].append([key, value])
        else:
            bucket = self.table[index]
            for i, v in enumerate(bucket):
                if v[0] == key:
                    bucket[i][1] = [v[0], value]
            break
    def delete(self, key)
        index = self.hash(key)
        bucket = self.table[index]
        for i, value in enumerate(bucket):
            if value[0] == key:
                del bucket[i]
                return True
            elif hash(i) < hash(len(bucket)): # Open addressing strategy
                new_index = (index + 1) % len(self.table)
                bucket.insert(new_index, [key] + list(value))
        return False

