"function minWindow(s, nums) {
    const n = s.length;
    const numCounts = Array(n).fill(0);
    for (let i = 0; i < n; i++) { numCounts[i] = nums.includes(i == 0 ? 0 : s[i - 1]) ? 1 : 0;
    }
    let left = 0, right = 0, minLen = Infinity;
    while (right < n) {
        const count = numCounts[right];
        if (count === numCounts[0]) { // all nums are present in the current window
            while (left <= right && count === numCounts[left]) { // try to minimize the window size
                minLen = Math.min(minLen, right - left + 1);
                while (right < n && nums[right] == s[right - left]) right++;
                left++;
            }
        }
        if (minLen === Infinity) break;
        right++;
    }
    return minLen > Infinity ? "No solution" : minLen;
}

