def fibonacci(n): 
    if n <= 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        fib = [0, 1]
        for i in range(3, n):
            fib.append(fib[i - 1] + fib[i - 2])
        return fib[n - 1]

